SELECT * FROM( SELECT MR.MDEXMN_RCORD_NO , H.HSPTL_NM , H.HSPTL_DRCTR , MR.MDEXMN_RCORD_DT , MR.MDEXMN_DGNSS_NM , H.HSPTL_NO , ( SELECT PD.DRUG_NM FROM prscrptn_drug PD WHERE PD.PRSCRPTN_NO = P.PRSCRPTN_NO ) AS DRUGNM FROM mdexmn_rcord MR LEFT OUTER JOIN hsptl H ON H.HSPTL_NO = MR.HSPTL_NO LEFT OUTER JOIN prscrptn P ON P.MDEXMN_RCORD_NO = MR.MDEXMN_RCORD_NO WHERE 1=1
AND MR.MDEXMN_DGNSS_NM = #{type2}
ORDER BY MR.MDEXMN_RCORD_DT DESC )LIST LIMIT #{startIndexNo}, #{pageSize}

SELECT COUNT(*) FROM( SELECT MR.MDEXMN_RCORD_NO , H.HSPTL_NM , H.HSPTL_DRCTR , MR.MDEXMN_RCORD_DT , MR.MDEXMN_DGNSS_NM , ( SELECT PD.DRUG_NM FROM prscrptn_drug PD WHERE PD.PRSCRPTN_NO = P.PRSCRPTN_NO ) AS drugNm FROM mdexmn_rcord MR LEFT OUTER JOIN hsptl H ON H.HSPTL_NO = MR.HSPTL_NO LEFT OUTER JOIN prscrptn P ON P.MDEXMN_RCORD_NO = MR.MDEXMN_RCORD_NO WHERE 1=1
AND MR.MDEXMN_DGNSS_NM = #{type2}
GROUP BY MR.MDEXMN_RCORD_NO,H.HSPTL_NM, H.HSPTL_DRCTR, MR.MDEXMN_RCORD_DT,MR.MDEXMN_DGNSS_NM,H.HSPTL_NO, drugNm )LIST

