INSERT INTO prscrptn_drug
	(
		DRUG_NM
		, DRUG_UNIT
		, DRUG_AMOUNT
		, DRUG_PD
		, PRSCRPTN_NO
	)
VALUES
	(
		#{drugNm}
		, #{drugUnit}
		, #{drugAmount}
		, #{drugPd}
		, #{prscrptnNo}
	)

INSERT INTO prscrptn
	(
		PARMACY_NO
		, ATCH_CODE
		, PRSCRPTN_DT
		, MDEXMN_RCORD_NO
	)
VALUES
	(
		#{parmacyNo}
		, #{atchCode}
		, #{prscrptnDt}
		, #{mdexmnRcordNo}
	)

