		#{hsptlNo}
		, #{parmacyNo}
		, #{chldrnNo}
		, #{mdexmnDoctrOpinion}
		, #{mdexmnDgnssNm}
		, #{mdexmnRcordDt}
		, #{mdexmnMdlrt}
		, #{mdexmnMemo}
		, #{mdexmnTy}
	)


INSERT INTO hsptl
	(
		HSPTL_NM
		, HSPTL_DRCTR
